css:
@font-face {
	font-family: "THSarabun";
	src: url("/assets/erpnext_thailand/fonts/THSarabun.ttf");
}
@page {
	size: A4 portrait;
	margin: 0;
}
* {
	box-sizing: border-box;
	margin: 0;
	padding: 0;
}
html,
body {
	margin: 0;
	padding: 0;
}
body {
	font-family:
		"Sarabun", "TH Sarabun New", "Noto Sans Thai", "THSarabun", Arial,
		sans-serif;
	font-size: 9pt;
	color: #111;
}

.print-format {
	padding: 0 !important;
	margin: 0 !important;
	min-height: unset !important;
	max-width: unset !important;
}
.print-format-preview {
	padding: 0 !important;
}
.page {
	width: 210mm;
	height: 297mm;
	position: relative;
	overflow: hidden;
	page-break-after: always;
	background-size: 210mm 297mm;
	background-repeat: no-repeat;
	font-family: "THSarabun", "Sarabun", Arial, sans-serif;
	font-size: 11pt;
	color: #111;
}
.page:last-child {
	page-break-after: auto;
}
.f {
	position: absolute;
	line-height: 1.08;
	white-space: normal;
}

.field {
	position: absolute;
	line-height: 1.08;
	white-space: nowrap;
}
.text-right {
	text-align: right;
}
.amount {
	text-align: right;
	font-variant-numeric: tabular-nums;
	white-space: nowrap;
}
.tr {
	text-align: right;
}
.tc {
	text-align: center;
}
.nowrap {
	white-space: nowrap;
	overflow: hidden;
}
.small {
	font-size: 9.5pt;
}
table {
	width: 100%;
	border-collapse: collapse;
	table-layout: fixed;
}
td {
	padding: 0.8mm 1mm;
	vertical-align: top;
	line-height: 1.05;
	word-break: break-word;
}

.page {
	background-image: url("/assets/connect_diagnostics_core/images/print_formats/ex_pv_1.jpg?v=20260603-jpgpdf1");
}

/* Header */
.voucher-no {
	top: 18.5mm;
	left: 149mm;
	width: 48mm;
	font-size: 10.5pt;
}
.voucher-date {
	top: 25mm;
	left: 149mm;
	width: 48mm;
	font-size: 10.5pt;
}
.remark-top {
	top: 43mm;
	left: 28mm;
	width: 165mm;
	font-size: 10pt;
}

/* Account table aligned to EX PV background */
.accounts {
	top: 63.5mm;
	left: 6mm;
	width: 198mm;
	font-size: 10pt;
}
.accounts table {
	table-layout: fixed;
	border-collapse: collapse;
}
.accounts td {
	padding: 1.1mm 1.5mm;
	height: 7mm;
	line-height: 1.05;
	vertical-align: top;
}
.col-account {
	width: 36mm;
	text-align: left;
}
.col-detail {
	width: 94mm;
	text-align: left;
}
.col-debit {
	width: 34mm;
	text-align: right;
}
.col-credit {
	width: 34mm;
	text-align: right;
}

/* Total row */
.total-debit {
	top: 218.5mm;
	left: 139mm;
	width: 28mm;
}
.total-credit {
	top: 218.5mm;
	left: 173mm;
	width: 28mm;
}

/* Signatures */
.prepared-by {
	top: 253.5mm;
	left: 34mm;
	width: 28mm;
	text-align: center;
}

.amount-words {
	top: 218.5mm;
	left: 12mm;
	width: 120mm;
	font-size: 10pt;
}
/* Match prototype print weight for ERP-filled text. */
.f,
.field,
.items,
.items td,
.refs,
.refs td,
.accounts,
.accounts td,
.amount-words,
.small,
.medium,
.big,
.payer-mark,
.income-desc,
.issue-date {
	font-weight: 700;
}
